CREATE TABLE CONGE_SOLDE (ID NUMBER(19) PRIMARY KEY, EMPLOYE_ID NUMBER(19) NOT NULL, ANNEE NUMBER(4) NOT NULL, JOURS_ACQUIS NUMBER(6,2) DEFAULT 0 NOT NULL, JOURS_UTILISES NUMBER(6,2) DEFAULT 0 NOT NULL, JOURS_REPORTES NUMBER(6,2) DEFAULT 0 NOT NULL, CONSTRAINT FK_CONGE_SOLDE_EMP FOREIGN KEY (EMPLOYE_ID) REFERENCES EMPLOYE(ID), CONSTRAINT UK_CONGE_SOLDE UNIQUE (EMPLOYE_ID, ANNEE));
CREATE SEQUENCE SEQ_CONGE_SOLDE START WITH 1 INCREMENT BY 1;
CREATE TABLE DEMANDE_CONGE (ID NUMBER(19) PRIMARY KEY, EMPLOYE_ID NUMBER(19) NOT NULL, TYPE_CONGE VARCHAR2(30) NOT NULL, DATE_DEBUT DATE NOT NULL, DATE_FIN DATE NOT NULL, JOURS_DEMANDES NUMBER(6,2) NOT NULL, MOTIF VARCHAR2(1000), STATUT VARCHAR2(20) DEFAULT 'EN_ATTENTE' NOT NULL, VALIDATEUR_ID NUMBER(19), DATE_VALIDATION TIMESTAMP, COMMENTAIRE_VALIDATION VARCHAR2(1000), CONSTRAINT FK_DEMANDE_CONGE_EMP FOREIGN KEY (EMPLOYE_ID) REFERENCES EMPLOYE(ID), CONSTRAINT FK_DEMANDE_CONGE_VAL FOREIGN KEY (VALIDATEUR_ID) REFERENCES EMPLOYE(ID));
CREATE SEQUENCE SEQ_DEMANDE_CONGE START WITH 1 INCREMENT BY 1;
COMMIT;
